// Safe 2-of-3 smart account helpers (Safe v1.4.1, Base Sepolia). Pure functions on top of viem: no network, no key.
// Source of truth: /shared. Copies are generated by `npm run sync-shared`.
// Custody model of the live demo: a Safe 2-of-3 smart account (NOT MPC). P1 client, P2 lawyer node, P3 Swissquote node.
import {
  concat, encodeAbiParameters, encodeFunctionData, erc20Abi, getAddress, getContractAddress, hashTypedData, isAddress, keccak256, parseAbi, toHex,
  zeroAddress, type Address, type Hex,
} from "viem";
import { CHAIN_ID } from "./constants";

/** Canonical Safe v1.4.1 deployments, identical on every chain. Verify with getCode before relying on them. */
export const SAFE_FACTORY: Address = "0x4e1DCf7AD4e460CfD30791CCC4F9c8a4f820ec67";
export const SAFE_SINGLETON_L2: Address = "0x29fcB43b46531BcA003ddC8FCB67FFE91900C762";
export const SAFE_FALLBACK_HANDLER: Address = "0xfd0732Dc9E303f09fCEf3a7388Ad10A83459Ec99";
/** Head of the owners linked list inside the Safe. */
export const SAFE_SENTINEL: Address = "0x0000000000000000000000000000000000000001";
export const SAFE_THRESHOLD = 2;

export const safeAbi = parseAbi([
  "function setup(address[] _owners, uint256 _threshold, address to, bytes data, address fallbackHandler, address paymentToken, uint256 payment, address paymentReceiver)",
  "function execTransaction(address to, uint256 value, bytes data, uint8 operation, uint256 safeTxGas, uint256 baseGas, uint256 gasPrice, address gasToken, address refundReceiver, bytes signatures) returns (bool)",
  "function swapOwner(address prevOwner, address oldOwner, address newOwner)",
  "function getOwners() view returns (address[])",
  "function getThreshold() view returns (uint256)",
  "function nonce() view returns (uint256)",
]);
export const safeFactoryAbi = parseAbi([
  "function createProxyWithNonce(address _singleton, bytes initializer, uint256 saltNonce) returns (address proxy)",
  "function proxyCreationCode() view returns (bytes)",
]);

/** A Safe transaction as this project uses it: a plain call (operation 0) with no gas refund. */
export type SafeTx = { to: Address; value: bigint; data: Hex };

/** Deterministic salt of the account, derived from its pseudonymous Swissquote reference. */
export function saltNonceFor(sqRef: string): bigint {
  return BigInt(keccak256(toHex(`sqkeys/safe-salt/v1:${sqRef.toLowerCase()}`)));
}

/** Owners in the fixed order [P1 client, P2 lawyer, P3 Swissquote]. */
export function safeInitializer(owners: readonly Address[], threshold: number = SAFE_THRESHOLD): Hex {
  if (owners.length !== 3) throw new Error("A SQ Keys Safe has exactly three owners");
  if (new Set(owners.map((o) => o.toLowerCase())).size !== 3) throw new Error("Safe owners must be distinct");
  return encodeFunctionData({
    abi: safeAbi, functionName: "setup",
    args: [[...owners], BigInt(threshold), zeroAddress, "0x", SAFE_FALLBACK_HANDLER, zeroAddress, 0n, zeroAddress],
  });
}

/** CREATE2 address of the proxy. `proxyCreationCode` is read once from the factory (it never changes). */
export function predictSafeAddress(args: { owners: readonly Address[]; threshold?: number; saltNonce: bigint; proxyCreationCode: Hex }): Address {
  const initializer = safeInitializer(args.owners, args.threshold);
  const salt = keccak256(concat([keccak256(initializer), encodeAbiParameters([{ type: "uint256" }], [args.saltNonce])]));
  const bytecode = concat([args.proxyCreationCode, encodeAbiParameters([{ type: "uint256" }], [BigInt(SAFE_SINGLETON_L2)])]);
  return getAddress(getContractAddress({ opcode: "CREATE2", from: SAFE_FACTORY, salt, bytecode }));
}

/** EIP-712 hash that the owners sign (the same value as Safe.getTransactionHash). */
export function safeTxHash(args: { safe: Address; tx: SafeTx; nonce: bigint; chainId?: number }): Hex {
  return hashTypedData({
    domain: { chainId: args.chainId ?? CHAIN_ID, verifyingContract: getAddress(args.safe) },
    types: {
      SafeTx: [
        { name: "to", type: "address" }, { name: "value", type: "uint256" }, { name: "data", type: "bytes" }, { name: "operation", type: "uint8" },
        { name: "safeTxGas", type: "uint256" }, { name: "baseGas", type: "uint256" }, { name: "gasPrice", type: "uint256" },
        { name: "gasToken", type: "address" }, { name: "refundReceiver", type: "address" }, { name: "nonce", type: "uint256" },
      ],
    },
    primaryType: "SafeTx",
    message: {
      to: getAddress(args.tx.to), value: args.tx.value, data: args.tx.data, operation: 0, safeTxGas: 0n, baseGas: 0n, gasPrice: 0n,
      gasToken: zeroAddress, refundReceiver: zeroAddress, nonce: args.nonce,
    },
  });
}

export function usdcTransferTx(usdc: Address, to: Address, amountBase: bigint): SafeTx {
  if (amountBase <= 0n) throw new Error("Amount must be positive");
  return { to: getAddress(usdc), value: 0n, data: encodeFunctionData({ abi: erc20Abi, functionName: "transfer", args: [getAddress(to), amountBase] }) };
}

/** Owner in the linked list that points at `owner` (the sentinel when `owner` is first). Throws if `owner` is not an owner. */
export function prevOwnerOf(owners: readonly Address[], owner: Address): Address {
  const i = owners.findIndex((o) => o.toLowerCase() === owner.toLowerCase());
  if (i < 0) throw new Error("Not an owner of this Safe");
  return i === 0 ? SAFE_SENTINEL : getAddress(owners[i - 1]);
}

/** Recovery: replace the old client key by the new one. Signed by P2 and P3. The Safe address does not change. */
export function swapOwnerTx(args: { safe: Address; owners: readonly Address[]; oldOwner: Address; newOwner: Address }): SafeTx {
  if (!isAddress(args.newOwner) || args.newOwner === zeroAddress || args.newOwner.toLowerCase() === SAFE_SENTINEL) throw new Error("Invalid new owner");
  if (args.owners.some((o) => o.toLowerCase() === args.newOwner.toLowerCase())) throw new Error("The new owner is already an owner");
  const prev = prevOwnerOf(args.owners, args.oldOwner);
  return {
    to: getAddress(args.safe), value: 0n,
    data: encodeFunctionData({ abi: safeAbi, functionName: "swapOwner", args: [prev, getAddress(args.oldOwner), getAddress(args.newOwner)] }),
  };
}

/** Safe wants the signatures concatenated and sorted by signer address, each over the safeTxHash (v = 27 or 28). */
export function packSignatures(sigs: readonly { signer: Address; signature: Hex }[]): Hex {
  const sorted = [...sigs].sort((a, b) => (BigInt(a.signer) < BigInt(b.signer) ? -1 : 1));
  if (new Set(sorted.map((s) => s.signer.toLowerCase())).size !== sorted.length) throw new Error("Duplicate signer");
  return concat(sorted.map((s) => s.signature));
}
